import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.B-YJpANp.js";const c=JSON.parse('{"title":"Listas y Rangos (CSV & Arrays) 📋","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lists-and-ranges.md","filePath":"guide/lists-and-ranges.md","lastUpdated":1789018250000}'),n={name:"guide/lists-and-ranges.md"};function l(r,s,o,p,h,d){return i(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="listas-y-rangos-csv-arrays-📋" tabindex="-1">Listas y Rangos (CSV &amp; Arrays) 📋 <a class="header-anchor" href="#listas-y-rangos-csv-arrays-📋" aria-label="Permalink to &quot;Listas y Rangos (CSV &amp; Arrays) 📋&quot;">​</a></h1><p>Uno de los mayores dolores de cabeza al integrar frontends y backends es la discordancia en la serialización de listas y rangos.</p><p>Diferentes librerías de frontend serializan listas de maneras distintas:</p><ul><li>Algunas envían parámetros repetidos o indexados: <code>filter[status][in][]=active&amp;filter[status][in][]=draft</code></li><li>Otras envían cadenas delimitadas por comas (CSV): <code>filter[status][in]=active,draft</code></li></ul><p><strong>Laravel ApiQueryBuilder resuelve esto de raíz: tolera ambas representaciones de forma 100% transparente.</strong></p><hr><h2 id="_1-pertenencia-a-conjunto-in" tabindex="-1">1. Pertenencia a Conjunto (<code>in</code>) <a class="header-anchor" href="#_1-pertenencia-a-conjunto-in" aria-label="Permalink to &quot;1. Pertenencia a Conjunto (`in`)&quot;">​</a></h2><p>Filtra registros cuyo valor coincida con cualquiera de los elementos proporcionados.</p><h3 id="formato-csv-recomendado-por-su-brevedad-en-url" tabindex="-1">Formato CSV (Recomendado por su brevedad en URL) <a class="header-anchor" href="#formato-csv-recomendado-por-su-brevedad-en-url" aria-label="Permalink to &quot;Formato CSV (Recomendado por su brevedad en URL)&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/orders?filter[status][in]=paid,shipped,delivered</span></span></code></pre></div><h3 id="formato-array-indexado" tabindex="-1">Formato Array Indexado <a class="header-anchor" href="#formato-array-indexado" aria-label="Permalink to &quot;Formato Array Indexado&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/orders?filter[status][in][]=paid&amp;filter[status][in][]=shipped&amp;filter[status][in][]=delivered</span></span></code></pre></div><p><strong>SQL generado en ambos casos:</strong></p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;paid&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shipped&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;delivered&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h2 id="_2-exclusion-de-conjunto-not-in" tabindex="-1">2. Exclusión de Conjunto (<code>not_in</code>) <a class="header-anchor" href="#_2-exclusion-de-conjunto-not-in" aria-label="Permalink to &quot;2. Exclusión de Conjunto (`not_in`)&quot;">​</a></h2><p>Filtra registros cuyo valor <strong>no</strong> se encuentre en la lista especificada.</p><h3 id="ejemplo-http" tabindex="-1">Ejemplo HTTP <a class="header-anchor" href="#ejemplo-http" aria-label="Permalink to &quot;Ejemplo HTTP&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/users?filter[role][not_in]=banned,suspended</span></span></code></pre></div><p><strong>SQL generado:</strong></p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> users </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> role</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;banned&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;suspended&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h2 id="_3-rango-cerrado-inclusivo-between" tabindex="-1">3. Rango Cerrado Inclusivo (<code>between</code>) <a class="header-anchor" href="#_3-rango-cerrado-inclusivo-between" aria-label="Permalink to &quot;3. Rango Cerrado Inclusivo (`between`)&quot;">​</a></h2><p>Para consultas donde se requiere exactamente un límite inferior y un límite superior:</p><h3 id="formato-csv" tabindex="-1">Formato CSV <a class="header-anchor" href="#formato-csv" aria-label="Permalink to &quot;Formato CSV&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/products?filter[price][between]=10,50</span></span></code></pre></div><h3 id="formato-array" tabindex="-1">Formato Array <a class="header-anchor" href="#formato-array" aria-label="Permalink to &quot;Formato Array&quot;">​</a></h3><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/products?filter[price][between][0]=10&amp;filter[price][between][1]=50</span></span></code></pre></div><p><strong>SQL generado:</strong></p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BETWEEN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Validación de 2 Elementos</p><p>El operador <code>between</code> valida estrictamente que se reciban al menos 2 valores. Si el cliente envía solo un valor (<code>?filter[price][between]=10</code>), el procesador responderá con <strong>HTTP 422</strong> indicando que el operador requiere dos valores.</p></div><hr><h2 id="_4-fuera-de-rango-not-between" tabindex="-1">4. Fuera de Rango (<code>not_between</code>) <a class="header-anchor" href="#_4-fuera-de-rango-not-between" aria-label="Permalink to &quot;4. Fuera de Rango (`not_between`)&quot;">​</a></h2><p>Filtra registros que se encuentren fuera del intervalo dado:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /api/events?filter[capacity][not_between]=100,500</span></span></code></pre></div><p><strong>SQL generado:</strong></p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> events </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> BETWEEN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div>',37)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
